{"file":"_scratch/windows-interrupted-owner-native-proposal02/durable_lifecycle.py","start":452,"end":555,"text":"452:                 record.reason = \"Final durable completion was not confirmed\"\n453:                 record.quarantine_persisted = False\n454:                 record.quarantine_failure_type = type(original).__name__\n455:             if isinstance(exc_value, BaseException):\n456:                 exc_value.add_note(\"Final durable completion failed: \" + type(original).__name__)\n457:                 return False\n458:             raise\n459:         return result\n460: \n461: \n462: class DurableOwnedRuntimeFactory:\n463:     def __init__(self, lifecycle):\n464:         if type(lifecycle) is not DurableSnapshotLifecycle:\n465:             raise LifecycleUnavailable(\"Exact durable lifecycle required\")\n466:         self.manager = lifecycle\n467: \n468:     def open_owned_session(self, profile, permit):\n469:         manager = self.manager\n470:         if type(permit) is not _NativePermit or permit.manager is not manager:\n471:             raise LifecycleUnavailable(\"The active lease's native permit is required\")\n472:         with manager._lock:\n473:             record = permit.record\n474:             if (manager._records.get(record.key) is not record or record.permit is not permit.identity\n475:                     or record.phase is not Phase.NATIVE_RESERVED or record.owner is not None):\n476:                 raise SessionClosed(\"Native permit is stale or already consumed\")\n477:             owner = OwnedSession(manager, record)\n478:             record.owner = owner\n479:         worker = None\n480:         try:\n481:             # Pending start remains NATIVE_RESERVED with its owner set. Other\n482:             # entrants cannot start it; lease exit can revoke without waiting\n483:             # for the journal flush or suspended-process preparation.\n484:             worker = manager._kernel.start_owned_worker(record.protection, permit.identity, profile)\n485:             with manager._lock:\n486:                 if record.phase is not Phase.NATIVE_RESERVED or owner._revoked:\n487:                     raise SessionClosed(\"Worker start was revoked before publication\")\n488:                 owner._worker = worker\n489:                 record.phase = Phase.NATIVE_RUNNING\n490:                 return owner\n491:         except BaseException as original:\n492:             if worker is not None:\n493:                 # A resumed worker may lose publication to lease revocation.\n494:                 # owner._worker is still None here; retain/use this exact owner.\n495:                 manager._kernel.stop_unpublished(worker, permit.identity, original)\n496:             with manager._lock:\n497:                 manager._quarantine_preserving(record, \"Owned worker start did not complete\", original)\n498:             manager._flush_quarantine(record.key, original)\n499:             raise\n500: \n501: \n502: class _DurableKernel:\n503:     def __init__(self, manager):\n504:         self.manager = manager\n505:         self._starts = {}\n506:         self._pending_quarantine = {}\n507: \n508:     def acquire_read(self, key):\n509:         self.manager._token(key)\n510:         return self.manager._delegate.acquire_read(key)\n511: \n512:     def _record(self, protection, permit):\n513:         with self.manager._lock:\n514:             matches = [r for r in self.manager._records.values()\n515:                        if r.protection is protection and r.permit is permit and r.owner is not None]\n516:             if len(matches) != 1:\n517:                 raise LifecycleUnavailable(\"Exact current owned record required\")\n518:             return matches[0]\n519: \n520:     def start_owned_worker(self, protection, permit, profile):\n521:         manager = self.manager\n522:         record = self._record(protection, permit)\n523:         token = manager._token(record.key)\n524:         worker = None\n525:         try:\n526:             worker = manager._delegate.create_suspended(protection, permit, profile)\n527:             if worker is None:\n528:                 raise LifecycleUnavailable(\"Suspended worker was not returned\")\n529:             self._starts[permit] = worker\n530:             manager._reservations.bind_worker(token, worker)\n531:             # Shared lock order is manager state, then reservation state. The\n532:             # fixed resume callback must be nonblocking; no file I/O here.\n533:             with manager._lock:\n534:                 if record.phase is not Phase.NATIVE_RESERVED or record.owner._revoked:\n535:                     raise SessionClosed(\"Start revoked before resume\")\n536:                 manager._reservations.resume_owned(token, manager._delegate.resume)\n537:             # Pipe bootstrap, adoption and policy acknowledgement may block.\n538:             # They complete outside both manager and reservation state locks.\n539:             if manager._delegate.finish_start(worker, permit, profile) is not True:\n540:                 raise LifecycleUnavailable(\"Owned startup completion unconfirmed\")\n541:             return worker\n542:         except BaseException as original:\n543:             try:\n544:                 manager._reservations.revoke_local(token)\n545:             except BaseException as revoke_error:\n546:                 original.add_note(\"Local revocation raised: \" + type(revoke_error).__name__)\n547:             if worker is not None:\n548:                 self.stop_unpublished(worker, permit, original)\n549:             raise\n550: \n551:     def stop_unpublished(self, worker, permit, original):\n552:         \"\"\"Retained identity, not PID data or owner publication, authorizes stop.\"\"\"\n553:         try:\n554:             if worker is None or self._starts.get(permit) is not worker:\n555:                 raise LifecycleUnavailable(\"Exact retained unpublished worker required\")"}
